selected.compute:
options = read('/input/options')
existing = read('/output/selection')
result = existing
if not valid(existing):
    result = []
    for group in combinations(options, goal['min_count']):
        ids = [record['id'] for record in group]
        if valid(ids):
            result = ids
            break

selected.effects:
if not valid(read('/output/selection')):
    write('/output/selection', result)
receipt_state = receipt('report')
if receipt_state == 'unattempted':
    send('report', 'team', read('/output/selection'))
elif receipt_state == 'unknown':
    delivery_state = status('report')
    if delivery_state == 'not_sent':
        send('report', 'team', read('/output/selection'))
if exists('/tmp/cache'):
    delete('/tmp/cache')
